CREATE TYPE "P2PListingMode" AS ENUM ('BUY', 'SELL', 'RENT');
CREATE TYPE "P2POrderStatus" AS ENUM ('PENDING_SIGNATURE', 'OPEN', 'MATCHED', 'SETTLED', 'CANCELLED');
CREATE TABLE "p2p_energy_listings" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"organization_id" UUID NOT NULL,"mode" "P2PListingMode" NOT NULL,"source" TEXT NOT NULL,"location" TEXT NOT NULL,"latitude" DECIMAL(9,6),"longitude" DECIMAL(9,6),"quantity_kwh" DECIMAL(18,6) NOT NULL,"available_kwh" DECIMAL(18,6) NOT NULL,"price_per_kwh" DECIMAL(18,8) NOT NULL,"currency" TEXT NOT NULL DEFAULT 'EUR',"delivery_start" TIMESTAMPTZ NOT NULL,"delivery_end" TIMESTAMPTZ NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX "p2p_energy_listings_location_mode_idx" ON "p2p_energy_listings" ("mode", "delivery_start");
CREATE TABLE "p2p_energy_orders" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"listing_id" UUID NOT NULL REFERENCES "p2p_energy_listings"("id") ON DELETE CASCADE,"buyer_id" UUID NOT NULL,"quantity_kwh" DECIMAL(18,6) NOT NULL,"total_amount" DECIMAL(18,8) NOT NULL,"wallet_address" TEXT,"signature" TEXT,"status" "P2POrderStatus" NOT NULL DEFAULT 'PENDING_SIGNATURE',"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX "p2p_energy_orders_buyer_status_idx" ON "p2p_energy_orders" ("buyer_id", "status");
